/**
 * Unit tests for CommandLineRunner.createOptions().
 */
public class CommandLineRunner_createOptions_TriageGen2Test {

  private PrintStream nullStream;

  @Before
  public void setUp() {
    nullStream = new PrintStream(new java.io.OutputStream() {
      @Override
      public void write(int b) {}
    });
  }

  /**
   * Helper subclass to access protected method createOptions.
   */
  private static class TestableCommandLineRunner extends CommandLineRunner {
    public TestableCommandLineRunner(String[] args) throws CmdLineException {
      super(args);
    }

    public CompilerOptions testCreateOptions() {
      return createOptions();
    }

    // Expose flags for manipulation if they are protected/package-private
    // In actual Closure Compiler, flags are usually static members of CommandLineRunner
  }

  @Test
  public void testCreateOptions_defaultSettings() throws CmdLineException {
    // Minimal args to satisfy constructor
    CommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
    CompilerOptions options = ((TestableCommandLineRunner) runner).testCreateOptions();

    assertThat(options).isNotNull();
    // Verification of coding convention via reflection or public API if available
    // Since we cannot see the internals of CompilerOptions easily, 
    // we check the side effects of the flags.
  }

  @Test
  public void testCreateOptions_withDebugTrue() throws CmdLineException {
    // Simulate flags.debug = true
    // Assuming flags are accessible or passed via args
    String[] args = {"--debug"};
    CommandLineRunner runner = new TestableCommandLineRunner(args);
    CompilerOptions options = ((TestableCommandLineRunner) runner).testCreateOptions();

    assertThat(options).isNotNull();
    // The logic level.setDebugOptionsForCompilationLevel(options) is executed
  }

  @Test
  public void testCreateOptions_withProcessClosurePrimitivesTrue() throws CmdLineException {
    String[] args = {"--process_closure_primitives"};
    CommandLineRunner runner = new TestableCommandLineRunner(args);
    CompilerOptions options = ((TestableCommandLineRunner) runner).testCreateOptions();

    assertThat(options.closurePass).isTrue();
  }

  @Test
  public void testCreateOptions_withFormattingOptions() throws CmdLineException {
    // Testing the loop: for (FormattingOption formattingOption : flags.formatting)
    // We pass multiple formatting flags
    String[] args = {"--format_option_1", "--format_option_2"};
    CommandLineRunner runner = new TestableCommandLineRunner(args);
    CompilerOptions options = ((TestableCommandLineRunner) runner).testCreateOptions();

    assertThat(options).isNotNull();
  }

  @Test
  public void testCreateOptions_withoutClosurePrimitives() throws CmdLineException {
    String[] args = {"--compilation_level=WHITESPACE"}; // dummy flag
    CommandLineRunner runner = new TestableCommandLineRunner(args);
    CompilerOptions options = ((TestableCommandLineRunner) runner).testCreateOptions();

    assertThat(options.closurePass).isFalse();
  }

  @Test
  public void testCreateOptions_allBranches() throws CmdLineException {
    // This test aims to hit:
    // 1. debug is true
    // 2. debug is false
    // 3. process_closure_primitives is true
    // 4. process_closure_primitives is false
    // 5. formatting list is not empty
    // 6. formatting list is empty

    // Case: All enabled
    String[] argsFull = {
        "--debug", 
        "--process_closure_primitives", 
        "--compilation_level=SIMPLE"
    };
    CommandLineRunner runnerFull = new TestableCommandLineRunner(argsFull);
    CompilerOptions optionsFull = ((TestableCommandLineRunner) runnerFull).testCreateOptions();
    assertThat(optionsFull.closurePass).isTrue();

    // Case: Minimal (No debug, no closure primitives, no formatting)
    String[] argsMin = {"--compilation_level=SIMPLE"};
    CommandLineRunner runnerMin = new TestableCommandLineRunner(argsMin);
    CompilerOptions optionsMin = ((TestableCommandLineRunner) runnerMin).testCreateOptions();
    assertThat(optionsMin.closurePass).isFalse();
  }
}
